WITH scored AS (SELECT *, AVG(monthly_fee) OVER (PARTITION BY status ORDER BY start_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS monthly_fee_avg_5, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY status, plan), 4) AS monthly_fee_share, NTILE(10) OVER (PARTITION BY DATE_TRUNC('week', end_date), status ORDER BY monthly_fee DESC, id) AS monthly_fee_bucket FROM subscriptions) SELECT CASE WHEN monthly_fee_share >= 0.74 THEN 'HIGH' ELSE 'LOW' END AS monthly_fee_share_tier, DATE_TRUNC('WEEK', start_date) AS week_start, COUNT(*) FILTER (WHERE plan = 'basic') AS basic_rows, ROUND(SUM(monthly_fee_share) / NULLIF(COUNT(CASE WHEN plan = 'standard' THEN 1 END), 0), 2) AS monthly_fee_share_per_standard, COUNT(*) FILTER (WHERE status = 'CANCELLED') AS cancelled_rows, COUNT(*) FILTER (WHERE status = 'EXPIRED') AS expired_rows, COUNT(*) FILTER (WHERE plan = 'premium') AS premium_rows FROM scored GROUP BY CASE WHEN monthly_fee_share >= 0.74 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', start_date) HAVING COUNT(*) FILTER (WHERE plan = 'premium') >= 1 ORDER BY expired_rows DESC;
